void iap_rd_device_ser (Iap_Sernum sernum)
{
  UInt32 arg_i [5] , arg_o [5] ;

  arg_i [0] = CMD_RD_DEVICE_SERNUM ;
    
  iap_execute (arg_i , arg_o) ;

//  convert_format :
    {
      UInt8   index =                            4 ;
      UInt8 * dest  = sernum + sizeof (Iap_Sernum) ;

      do
        {
          UInt32 num_part = arg_o [index] ;

          *--dest = (UInt8) num_part ; num_part >>= 8 ;
          *--dest = (UInt8) num_part ; num_part >>= 8 ;
          *--dest = (UInt8) num_part ; num_part >>= 8 ;
          *--dest = (UInt8) num_part ;
        }
      while (--index) ;
    }
}

